def reverseWords(s):
    words = []
    current_word = []
    i = 0
    n = len(s)

    while i < n:
        if s[i].isspace():
            if current_word:
                words.append(''.join(current_word))
                current_word = []
        else:
            current_word.append(s[i])
        i += 1

    if current_word:
        words.append(''.join(current_word))

    # Reverse the list of words
    words.reverse()

    # Reconstruct the string preserving original whitespace
    result = []
    i = 0
    n = len(s)
    word_idx = 0

    while i < n:
        if s[i].isspace():
            # Append all consecutive whitespace characters
            while i < n and s[i].isspace():
                result.append(s[i])
                i += 1
        else:
            # Append the next word
            if word_idx < len(words):
                result.append(words[word_idx])
                word_idx += 1
            i += 1

    return ''.join(result)
```

