def capitalize_words(sentence):
    result = []
    current_word = []

    for char in sentence:
        if char.isalpha():
            if not current_word:
                # Start of a new word: capitalize first letter
                current_word.append(char.upper())
            else:
                # Rest of the word: lowercase
                current_word.append(char.lower())
        else:
            # Non-alphabetic character: end of current word if any
            if current_word:
                result.append(''.join(current_word))
                current_word = []
            result.append(char)

    # Append the last word if the sentence doesn't end with a non-alphabetic character
    if current_word:
        result.append(''.join(current_word))

    return ''.join(result)
