def unique_sorted_elements(input_list):
    # Step 1: Remove duplicates manually using a list
    unique_list = []
    for num in input_list:
        is_duplicate = False
        for existing in unique_list:
            if existing == num:
                is_duplicate = True
                break
        if not is_duplicate:
            unique_list.append(num)

    # Step 2: Sort the unique list using selection sort
    n = len(unique_list)
    for i in range(n):
        min_index = i
        for j in range(i + 1, n):
            if unique_list[j] < unique_list[min_index]:
                min_index = j
        # Swap
        unique_list[i], unique_list[min_index] = unique_list[min_index], unique_list[i]

    return unique_list
```

