def three_sum_exists(numbers, target):
    n = len(numbers)
    if n < 3:
        return False

    # Sort the array to use two-pointer technique
    sorted_numbers = sorted(numbers)

    for i in range(n - 2):
        # Skip duplicate values for the first element to avoid redundant checks
        if i > 0 and sorted_numbers[i] == sorted_numbers[i - 1]:
            continue

        left = i + 1
        right = n - 1

        while left < right:
            current_sum = sorted_numbers[i] + sorted_numbers[left] + sorted_numbers[right]

            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return False
```

