def find_cube_root(x, eps):
    if x == 0.0:
        return 0.0.0

    # Determine search interval [a, b] such that a^3 <= x <= b^3
    if x > 0:
        a, b = 0.0, max(1.0, x)
        # Expand b if needed
        while b**3 < x:
            b *= 2.0
    else:
        a, b = min(-1.0, x), 0.0
        # Expand a if needed (more negative)
        while a**3 > x:
            a *= 2.0

    # Bisection search
    for _ in range(1000):  # Sufficient iterations for required precision
        mid = (a + b) / 2.0
        val = mid**3
        if abs(val - x) < eps:
            return mid
        if val < x:
            a = mid
        else:
            b = mid

    return (a + b) / 2.0
