def generate_vm_network_config(port_configs):
    if not port_configs:
        return ""

    # Dictionary to store unique mappings: key = (host_port, vm_port), value = host_ip
    # We prioritize non-empty host_ip. If a mapping already exists with a non-empty IP,
    # we keep it. If the existing one is empty and we find a non-empty one, we update.
    mapping = {}

    for config in port_configs:
        host_ip = config.get("host_ip", "")
        host_port = config.get("host_port")
        vm_port = config.get("vm_port")

        if host_port is None or vm_port is None:
            continue

        key = (host_port, vm_port)

        if key not in mapping:
            mapping[key] = host_ip
        else:
            # If current stored IP is empty and new one is not, update
            if mapping[key] == "" and host_ip != "":
                mapping[key] = host_ip
            # If both are non-empty, we keep the first encountered (no change needed)
            # If both are empty, no change needed

    # Build the command string
    parts = []
    for (host_port, vm_port), host_ip in mapping.items():
        if host_ip == "":
            # Format: -p host_port:vm_port
            parts.append(f"-p {host_port}:{vm_port}")
        else:
            # Format: -p host_ip:host_port:vm_port
            parts.append(f"-p {host_ip}:{host_port}:{vm_port}")

    return " ".join(parts)
