def merge_labels(connect, list_connections):
    from collections import defaultdict, deque

    # Build adjacency list (undirected)
    graph = defaultdict(set)
    for node, neighbors in connect.items():
        graph[node].update(neighbors)
        for neighbor in neighbors:
            graph[neighbor].add(node)

    visited = set()
    groups = []

    def bfs(start):
        component = []
        queue = deque([start])
        visited.add(start)
        while queue:
            node = queue.popleft()
            component.append(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return component

    for node in list_connections:
        if node not in visited:
            component = bfs(node)
            groups.append(sorted(component))

    # Create result dictionary with sorted keys and sorted values
    result = {}
    for group in groups:
        for label in group:
            result[label] = group

    # Ensure all keys are present and values are sorted (already sorted by construction)
    # Sort the dictionary items by key for consistent output order (optional but clean)
    sorted_result = {k: result[k] for k in sorted(result.keys())}
    return sorted_result
