def encrypt_message(message, shift):
    result = []
    for char in message:
        if 'a' <= char <= 'z':
            # Shift lowercase letters
            offset = ord('a')
            shifted = (ord(char) - offset + shift) % 26 + offset
            result.append(chr(shifted))
        elif 'A' <= char <= 'Z':
            # Shift uppercase letters
            offset = ord('A')
            shifted = (ord(char) - offset + shift) % 26 + offset
            result.append(chr(shifted))
        else:
            # Non-alphabetic characters remain unchanged
            result.append(char)
    return ''.join(result)
