def length_of_lis(nums):
    if not nums:
        return 0

    n = len(nums)
    tails = []  # tails[i] is the smallest tail of all increasing subsequences of length i+1

    for x in nums:
        # Use binary search to find the insertion point
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < x:
                left = mid + 1
            else:
                right = mid
        if left == len(tails):
            tails.append(x)
        else:
            tails[left] = x

    return len(tails)
```

```python
def min_distance(s: str, t: str) -> int:
    m, n = len(s), len(t)
    # dp[i][j] = minimum operations to transform s[:i] into t[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases
    for i in range(m + 1):
        dp[i][0] = i  # delete all characters from s[:i]
    for j in range(n + 1):
        dp[0][j] = j  # insert all characters of t[:j]

    # Fill DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # deletion
                    dp[i][j - 1],      # insertion
                    dp[i - 1][j - 1]   # substitution
                )

    return dp[m][n]
```

