def most_common_word(paragraph, banned):
    # Convert banned list to a set of lowercase words for O(1) lookup
    banned_set = set(word.lower() for word in banned)

    # Normalize paragraph: replace non-alphabetic characters with spaces
    # We'll do this manually without using built-in split or replace on the whole string
    words = []
    current_word = []
    for char in paragraph:
        if char.isalpha():
            current_word.append(char.lower())
        else:
            if current_word:
                words.append("".join(current_word))
                current_word = []
    if current_word:
        words.append("".join(current_word))

    # Manual frequency counting using a dictionary
    freq = {}
    for w in words:
        if w in banned_set:
            continue
        if w in freq:
            freq[w] += 1
        else:
            freq[w] = 1

    # Find the word with the maximum frequency manually
    most_common = ""
    max_count = -1
    for w in freq:
        if freq[w] > max_count:
            max_count = freq[w]
            most_common = w

    return most_common
