def validate_input(s):
    # Check for empty string
    if len(s) == 0:
        return False

    # Check for leading whitespace
    i = 0
    while i < len(s) and s[i] == ' ':
        i += 1
    if i != 0:
        return False

    # Check for trailing whitespace
    j = len(s) - 1
    while j >= 0 and s[j] == ' ':
        j -= 1
    if j != len(s) - 1:
        return False

    # If the string is now empty after stripping (all spaces), return False
    if i > j:
        return False

    # Determine if it's a sign
    is_negative = False
    if s[i] == '-':
        is_negative = True
        i += 1
    elif s[i] == '+':
        i += 1

    # If we've consumed the whole string with only sign, it's invalid
    if i == len(s):
        return False

    # Validate remaining characters are digits
    while i < len(s):
        c = s[i]
        if c < '0' or c > '9':
            return False
        i += 1

    return True
